 "content": "def transform(grid):
    """Copy each boundary color strip to the row of matching isolated markers.

    A marker is aligned with the matching color's position in its source strip.
    Any part of a copied strip beyond the grid's horizontal boundary is clipped.
    """
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The source strips are contiguous nonzero runs along the top or bottom edge.
    sources = []
    for r in (0, h - 1):
        c = 0
        while c < w:
            if grid[r][c] == 0:
                c += 1
                continue
            start = c
            while c < w and grid[r][c] != 0:
                c += 1
            if c - start > 1:
                sources.append(grid[r][start:c])

    for r in range(h):
        for c, color in enumerate(grid[r]):
            if color == 0:
                continue
            # Skip cells that are part of a horizontal run; these are source strips.
            if (c > 0 and grid[r][c - 1] != 0) or (c + 1 < w and grid[r][c + 1] != 0):
                continue
            # The boundary source runs themselves are not marker cells.
            if r in (0, h - 1) and sum(value != 0 for value in grid[r]) > 1:
                continue

            matching = [source for source in sources if color in source]
            if not matching:
                continue
            source = matching[0]
            start = c - source.index(color)
            for offset, value in enumerate(source):
                target_col = start + offset
                if 0 <= target_col < w:
                    out[r][target_col] = value

    return out


